CREATE TABLE client (nom VARCHAR(255) NOT NULL, prenom VARCHAR(255) NOT NULL, email VARCHAR(191) NOT NULL, telephone VARCHAR(255) DEFAULT NULL, id VARCHAR(39) NOT NULL, UNIQUE INDEX UNIQ_C7440455E7927C74 (email), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE service (nom VARCHAR(255) NOT NULL, description LONGTEXT DEFAULT NULL, actif TINYINT NOT NULL, id VARCHAR(39) NOT NULL, montant DOUBLE PRECISION NOT NULL, devise VARCHAR(3) NOT NULL, date_application DATETIME NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE messenger_messages (id BIGINT AUTO_INCREMENT NOT NULL, body LONGTEXT NOT NULL, headers LONGTEXT NOT NULL, queue_name VARCHAR(190) NOT NULL, created_at DATETIME NOT NULL, available_at DATETIME NOT NULL, delivered_at DATETIME DEFAULT NULL, INDEX IDX_75EA56E0FB7336F0E3BD61CE16BA31DBBF396750 (queue_name, available_at, delivered_at, id), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
ALTER TABLE entree_carnet ADD CONSTRAINT FK_DC419094590947D0 FOREIGN KEY (carnet_sante_id) REFERENCES carnet_sante (id);